#!/usr/bin/env python3
"""FS3 v191 - the real ship model in the rearm window, mission start, DONE.

    3D          The picture of your ship in the rearm window is now the
                MediaVP model, drawn with WebGL: it turns while the pointer
                is on it, the wheel zooms in and loads the finer model with
                sharper textures. The models live in models/<hull>/ next
                to the game and are fetched the first time a hull is shown
                (about 200 KB each, 600-900 KB with the fine level). Without
                WebGL, or while one loads, the sprite stands in as before.
                build.sh copies models/ to the web folder like the music.
    Missions    Every new mission starts with full hull, full racks and a
                charged weapon store (Silvio). Since v186 the racks were not
                refilled at all.
    Rearm       A refit no longer recharges the weapon store (Silvio: that
                was a free recharge in the middle of a fight). A DONE button
                closes the window and says the fit is kept; a longer list of
                weapons closes up its rows instead of running into it.

Needs v190. Edits src/, build.sh, .gitignore and two simulations; adds
src/58_model3d.js. The models come separately in models_v191.zip. Run
assemble.py afterwards.
"""
import base64
import os
import sys

if "BLAST_PX_PER_M" not in open("src/56_banks.js", encoding="utf-8").read():
    sys.exit("Abbruch: erst v190 einspielen.")
if os.path.exists("src/58_model3d.js"):
    sys.exit("Abbruch: v191 ist schon eingespielt.")

F = {}
def load(p):
    if p not in F: F[p] = open(p, encoding="utf-8").read()
def rep(p, old, new, count=1):
    load(p)
    n = F[p].count(old)
    if n != count:
        sys.exit("Abbruch (%s): Suchtext %d-mal gefunden, erwartet %d.\n%s" % (p, n, count, old[:200]))
    F[p] = F[p].replace(old, new)
rep('src/60_effects.js',
    '  }\n  // Tickets carry over, the pickups on the field do not.\n  ITEMS=[];\n  // Ordnance was only ever set at launch, so after the first boss there\n  // was nothing left for the rest of the run. Hull is deliberately not\n  // restored here: that is what the repair pickups are for.\n  // In the campaign the roster grows as the briefings hand it over; the\n  // newest unlocked hull is assigned and the switch button stays hidden.\n  if(FS1_MODE){\n',
    '  }\n  // Tickets carry over, the pickups on the field do not.\n  ITEMS=[];\n  // Every mission starts with the ship as it left the hangar (v191,\n  // Silvio): full hull, every rack full, the weapon store charged. Since\n  // v186 the racks live in the banks; secAmmo alone filled nothing.\n  // The repair pickups are for the fight itself.\n  // In the campaign the roster grows as the briefings hand it over; the\n  // newest unlocked hull is assigned and the switch button stays hidden.\n  if(FS1_MODE){\n')
rep('src/60_effects.js',
    '    if(un.length && player.ship!==un[un.length-1]) applyShip(un[un.length-1]);\n  }\n  player.secAmmo=player.secMax;\n  // Before the prototypes come through, nobody in the fleet has a shield.\n  // maxSh is left standing so the HUD bar keeps its geometry and simply\n  // reads empty, which is the correct picture rather than a missing one.\n',
    '    if(un.length && player.ship!==un[un.length-1]) applyShip(un[un.length-1]);\n  }\n  player.secAmmo=player.secMax;\n  // Refill what is fitted - a mission may have handed out its own rack\n  // (M57 Stiletto, M67 TAG-C), so the fit itself is left alone.\n  for(const sb of (player.sb||[])) sb.ammo=sb.max;\n  if(player.enMax>0) player.en=player.enMax;\n  player.secTimer=0;\n  // Before the prototypes come through, nobody in the fleet has a shield.\n  // maxSh is left standing so the HUD bar keeps its geometry and simply\n  // reads empty, which is the correct picture rather than a missing one.\n')
rep('src/60_effects.js',
    '    player.hp=Math.round(player.maxHp*frac);\n    player.hullMult=pm;\n  }\n  capBomberLeft=CAP_BOMBER_WAVES;capBomberCd=0;}\n\n// ── UPDATE ───────────────────────────────────────────────────\n',
    '    player.hp=Math.round(player.maxHp*frac);\n    player.hullMult=pm;\n  }\n  player.hp=player.maxHp;\n  capBomberLeft=CAP_BOMBER_WAVES;capBomberCd=0;}\n\n// ── UPDATE ───────────────────────────────────────────────────\n')
rep('src/70_ui.js',
    'function applyLoadout(keepSec){\n  setBanks(player.ship, fitFor(player.ship), keepSec);\n}\n// A refit fills every rack and the weapon store. This is what makes the\n// panel a rearm rather than a swap, and it is the whole reason a corvette on\n// the field is worth keeping.\nfunction rearmFull(){\n  player.en = null;\n  applyLoadout();\n  player.secTimer = 0;\n}\n',
    'function applyLoadout(keepSec){\n  setBanks(player.ship, fitFor(player.ship), keepSec);\n}\n// A refit fills every rack. This is what makes the panel a rearm rather\n// than a swap, and it is the whole reason a corvette on the field is worth\n// keeping. The weapon store keeps its charge (v191, Silvio): a refit in the\n// middle of a fight was a free recharge.\nfunction rearmFull(){\n  applyLoadout();\n  player.secTimer = 0;\n}\n')
rep('src/70_ui.js',
    "  (player.sb||[]).forEach(function(b, i){ banks.push({slot:'s'+i, label:'SECONDARY '+(i+1), key:b.key, ammo:b.max, x:c1, y:y, w:RM_C1_W, h:RM_BANK_H, num:++n}); y += RM_BANK_H+4; });\n  if(!rmBankKey(rmBank)) rmBank = banks.length ? banks[0].slot : 'p0';\n  const pri = rmPri(rmBank), cur = rmBankKey(rmBank);\n  const list = [];\n  y = my+60;\n  for(const w of bankChoices(player.ship, pri)){\n    list.push({key:w.key, w:w, open:weaponOpenFor(w, player.ship), cur:w.key===cur,\n               x:c2, y:y, wd:RM_C2_W, h:RM_ROW_H});\n    y += RM_ROW_H+RM_ROW_GAP;\n  }\n  return {mx:mx, my:my, mw:RM_W, mh:RM_H, c1:c1, c2:c2, c3:c3, c3w:mx+RM_W-RM_PAD-c3,\n          banks:banks, list:list, pri:pri};\n",
    "  (player.sb||[]).forEach(function(b, i){ banks.push({slot:'s'+i, label:'SECONDARY '+(i+1), key:b.key, ammo:b.max, x:c1, y:y, w:RM_C1_W, h:RM_BANK_H, num:++n}); y += RM_BANK_H+4; });\n  if(!rmBankKey(rmBank)) rmBank = banks.length ? banks[0].slot : 'p0';\n  const pri = rmPri(rmBank), cur = rmBankKey(rmBank);\n  const list = [], choices = bankChoices(player.ship, pri);\n  // A longer list closes up its rows rather than running into the DONE\n  // button (v191, Silvio): today's longest is 10 and still fits as it is.\n  const step = Math.min(RM_ROW_H+RM_ROW_GAP, Math.floor((RM_H-58-8-60)/Math.max(1, choices.length)));\n  y = my+60;\n  for(const w of choices){\n    list.push({key:w.key, w:w, open:weaponOpenFor(w, player.ship), cur:w.key===cur,\n               x:c2, y:y, wd:RM_C2_W, h:step-RM_ROW_GAP});\n    y += step;\n  }\n  return {mx:mx, my:my, mw:RM_W, mh:RM_H, c1:c1, c2:c2, c3:c3, c3w:mx+RM_W-RM_PAD-c3,\n          banks:banks, list:list, pri:pri};\n")
rep('src/70_ui.js',
    "function drawRearmShip(x, y, w, h){\n  const key = player.ship, img = IMGS[key];\n  ctx.fillStyle = TH('back'); ctx.fillRect(x, y, w, h);\n  if(!img || !img.width || !img.height) return;\n  const sc = Math.min((w-20)/img.width, (h-12)/img.height);\n  if(!(sc > 0)) return;\n",
    "function drawRearmShip(x, y, w, h){\n  const key = player.ship, img = IMGS[key];\n  ctx.fillStyle = TH('back'); ctx.fillRect(x, y, w, h);\n  window._rearmShipRect = {x:x, y:y, w:w, h:h};\n  // The real model when it is there (v191): it turns while the pointer is\n  // on it, the wheel zooms in and brings the finer model. The sprite\n  // stands in while it loads and wherever WebGL is missing.\n  const hot = hovering(x, y, w, h);\n  if(typeof m3dDraw === 'function' && m3dDraw(key, x, y, w, h, m3dView(key, hot))){\n    ctx.textAlign='right'; ctx.textBaseline='middle';\n    ctx.fillStyle = hot ? TH('accent') : TH('textDim'); ctx.font = thLabel(7);\n    ctx.fillText(hot ? 'WHEEL: ZOOM' : 'POINT TO TURN', x+w-6, y+8);\n    ctx.textAlign='left';\n    return;\n  }\n  if(!img || !img.width || !img.height) return;\n  const sc = Math.min((w-20)/img.width, (h-12)/img.height);\n  if(!(sc > 0)) return;\n")
rep('src/70_ui.js',
    "  ctx.fillText(L.pri ? ((player.pb||[]).length > 1 ? 'WHEEL UP / Q  -  bank 1, bank 2, linked' : 'ONE PRIMARY BANK')\n                     : 'WHEEL DOWN / E  -  next missile bank', C3+12, cy);\n\n  ctx.textAlign='center'; ctx.fillStyle=TH('textDim'); ctx.font=thValue(9, false);\n  ctx.fillText('1-'+L.banks.length+' bank  -  UP / DOWN and ENTER weapon  -  ESC or tap outside to cancel', mx+L.mw/2, my+L.mh-10);\n  ctx.restore();\n  ctx.textAlign='left'; ctx.textBaseline='top';\n}\n",
    "  ctx.fillText(L.pri ? ((player.pb||[]).length > 1 ? 'WHEEL UP / Q  -  bank 1, bank 2, linked' : 'ONE PRIMARY BANK')\n                     : 'WHEEL DOWN / E  -  next missile bank', C3+12, cy);\n\n  // Close (v191, Silvio): every pick is fitted the moment it is made, so\n  // the button says that closing keeps it.\n  const dx = L.c2, dy = my+RM_H-58, dw = RM_C2_W, dh = 30, dh2 = hovering(dx, dy, dw, dh);\n  thButton(dx, dy, dw, dh, 'on');\n  if(dh2) thGlowPath(dx, dy, dw, dh, 4, 0.9);\n  ctx.textAlign='center'; ctx.fillStyle=TH('textBright'); ctx.font=thValue(12, true);\n  ctx.fillText('DONE', dx+dw/2, dy+11);\n  ctx.fillStyle=TH('accentWarm'); ctx.font=thLabel(7);\n  ctx.fillText('YOUR FIT IS KEPT', dx+dw/2, dy+23);\n  window._rearmRects.push({x:dx, y:dy, w:dw, h:dh, close:true});\n  ctx.textAlign='center'; ctx.fillStyle=TH('textDim'); ctx.font=thValue(9, false);\n  ctx.fillText('1-'+L.banks.length+' bank  -  UP / DOWN and ENTER weapon  -  every pick is fitted at once  -  ESC closes', mx+L.mw/2, my+L.mh-10);\n  ctx.restore();\n  ctx.textAlign='left'; ctx.textBaseline='top';\n}\n")
rep('src/70_ui.js',
    '  if(rearmMenu){\n    for(const r of (window._rearmRects||[]))\n      if(p.x>=r.x&&p.x<=r.x+r.w&&p.y>=r.y&&p.y<=r.y+r.h){\n        if(r.bank) rmSelectBank(r.bank);\n        else if(r.key){ rmShow = r.key; if(r.open) fitWeapon(rmBank, r.key); }\n        return true; }\n',
    '  if(rearmMenu){\n    for(const r of (window._rearmRects||[]))\n      if(p.x>=r.x&&p.x<=r.x+r.w&&p.y>=r.y&&p.y<=r.y+r.h){\n        if(r.close){ setRearmMenu(false); return true; }\n        if(r.bank) rmSelectBank(r.bank);\n        else if(r.key){ rmShow = r.key; if(r.open) fitWeapon(rmBank, r.key); }\n        return true; }\n')
